**JavaScript (script.js):**

```javascript
document.addEventListener('DOMContentLoaded', function() {
    // Mendapatkan elemen-elemen pengalihan
    const links = document.querySelectorAll('nav a');

    // Fungsi untuk mengarahkan pengguna ke panganggo yang dipilih
    function redirectToSection(sectionId) {
        window.location.hash = sectionId;
    }

    // Menambahkan event listener pada setiap tautan
    links.forEach(link => {
        link.addEventListener('click', (event) => {
            event.preventDefault();
            const targetSection = link.getAttribute('href').substring(1); // Mengambil ID panganggo dari tautan
            redirectToSection(targetSection);
        });
    });
});
```

